def clean(t):
 t=re.sub(r'^(Describe how to |Describe |Perform |Apply |Comply with |Identify |Demonstrate )','',t,flags=re.I).strip();return t[:1].upper()+t[1:]
def fig(id,anchor):
 f=figs[id];src=f'<a href="{E(f["source_link"],quote=True)}">Full source context</a>.' if f.get('source_link') else ''
 return f'<figure class="learning-figure {"manual" if not f["file"].endswith(".svg") else "diagram"}" id="{anchor}"><p class="figure-title">{E(f["title"])}</p><a href="{E(f["file"],quote=True)}"><img src="{E(f["file"],quote=True)}" alt="{E(f["alt"],quote=True)}" loading="eager"></a><figcaption><strong>Note.</strong> {E(f["credit"])} {src}</figcaption></figure>'
# Source references are attached to each chapter, not an unexplained bibliography elsewhere.
cat={x['id']:x for x in json.loads((A/'caterpillar/catalogue.json').read_text())['documents']};lib=json.loads((A/'readiness/catalogue.json').read_text());sources={x['id']:x for x in lib['documents']+lib['web_documents']};coverage={x['code']:x for x in csv.DictReader((A/'readiness/coverage-data.psv').open(),delimiter='|')};ms=json.loads((A/'ms-4/book-map.json').read_text());chapters={x['chapter']:x for x in ms['sections'] if x.get('chapter')}
def source(key):
 if key.startswith('ms4:'):
  n=int(key.split(':')[1]);c=chapters[n];return f'Asphalt Institute. (2007). The asphalt handbook (7th ed., MS-4), Chapter {n}: {c["title"]}; source PDF pp. {c["pdf_start"]}–{c["pdf_end"]}.',f'../../ms-4/reader/chapter-{n:02}-01.html'
 if key.startswith('cat:'):
  c=cat['CAT-'+key[4:]];return f'Caterpillar. ({c.get("publication_year") or "n.d."}). {c["title"]} ({c.get("publication","publication identity in source")}). {c["model_scope"]}',f'../../caterpillar/index.html#CAT-{key[4:]}'
 if key in sources:
  s=sources[key];return f'{s["author"]}. ({s["edition"]}). {s["title"]}.',f'../../readiness/'+('web/'+key+'.html' if s['kind']=='web' else 'index.html#'+key)
 fixed={
 'cat-library':('Caterpillar. (Various editions). Paving, compaction, milling and machine publications; identify the applicable document/model.','../../caterpillar/index.html'),
 'cat-atlas':('Caterpillar. (Various editions). Original machine component figures, with publication/page/model records.','../../caterpillar/parts-atlas.html'),
 'whmis':('Canadian Centre for Occupational Health and Safety. (2026 retrieved). WHMIS pictograms and supporting information.','../../whmis/index.html'),
 'spec2006':('British Columbia Ministry of Transportation. (2006). Design build standard specifications, Section 502; PDF pp. 297–318. Historical contract exercise.','../../sources/design_build_standard_specs_2006.pdf#page=297'),
 'rosco-rb50-manual':('Rosco / LeeBoy. (n.d.). RB50 Broom: Operations, service and parts manual (1017258-03, Rev. B). Serial 255027 and above.','sources/rosco-rb50-manual.pdf'),
 'metro-air-regulation':('Metro Vancouver. (n.d.). Air Quality Regulatory Program. Current program locator, accessed 30 October 2026; verify actual permit requirements.','https://metrovancouver.org/services/environmental-regulation-enforcement/air-quality-regulatory-program'),
 'leeboy-8680':('LeeBoy. (2026). 8680 Commercial Paver: Safety and operations manual (1033428-SOP). Serial 365152 and above. Components pp. 3-1–3-32; operation pp. 4-1–4-68; maintenance section 5.','../../manuals/pdfs/leeboy-8680-safety-operations-1033428-sop.pdf'),
 }
 if key not in fixed:raise KeyError(key)
 return fixed[key]
def references(d):
 o=O[d['code']];items=[f'<li>SkilledTradesBC. (2016). <em>Asphalt Paving/Laydown Technician program outline</em>, {d["code"]}, printed p. {o["printed_start"]}; <a href="../../sources/asphalt-paving-laydown-technician-program-outline-august-2016.pdf#page={o["pdf_start"]}">source PDF pp. {o["pdf_start"]}–{o["pdf_end"]}</a>.</li>']
 keys=coverage[d['code']]['sources'].split(',')+d.get('additional_sources',[])
 if d['code'][0] in ['I','J']:keys+=['leeboy-8680']
 if d['code'][0]=='L':keys+=['cat:10']
 for key in dict.fromkeys(keys):
  label,href=source(key);items.append(f'<li>{E(label)} <a href="{E(href,quote=True)}">Open publication</a>.</li>')
 return '<section class="references"><h2>Sources and further reading</h2><ul>'+''.join(items)+'</ul><p>Figure-specific pages, editions and original contributors are credited beside each image. Current project requirements and the matching machine instructions determine practical use.</p></section>'
def practical(d,answers=False):
 criteria=d['practical'];critical=['Safe access, surroundings and communication maintained.','Required energy, heat, movement and public-access controls maintained for the actual task.']
 rows=[]
 for x in critical:rows.append(f'<tr><td><strong>Critical:</strong> {E(x)}</td><td>Pass / hold</td><td>Observation: __________________</td></tr>')
 for x in criteria:rows.append(f'<tr><td>{E(x)}</td><td>0 / 1 / 2</td><td>Evidence/help: ________________</td></tr>')
 threshold=d.get('assessment_threshold');rule=(f'The outline specifies a minimum 80% checklist result for this task. Score the {len(criteria)} task criteria out of {len(criteria)*2}; require at least {__import__("math").ceil(len(criteria)*2*.8)} points and all critical items passed. This local scoring rubric operationalizes the checklist; it is not a separate certification.' if threshold else 'Record each criterion as 0—not yet demonstrated, 1—with task-solving support, or 2—independently under the stated conditions. Mark unobserved criteria separately; do not convert missing opportunity into a zero. The assessor determines the required repeat practice and applicable qualification requirements.')
 return f'<section><h2>{"Instructor observation record" if answers else "Show the skill in supervised practice"}</h2><p>Machine/model/serial or classroom case: __________ · Manual/procedure and revision: __________ · Date/location: __________ · Learner/observer: __________</p><p>{E(rule)} A critical failure means hold, correction and reassessment regardless of the numerical result. Use safe simulations for classroom reasoning; actual operation requires the selected equipment, approved conditions and competent supervision.</p><table class="assessment"><thead><tr><th scope="col">What the observer checks</th><th scope="col">Result</th><th scope="col">Evidence</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table><p>Actual conditions and support: __________________________</p><p>Feedback, next practice and authorized release/status: __________________________</p></section>'
def quiz(d,answers=False):
 if 'quiz' not in d:return ''
 q=d['quiz'];body=f'<section><h2>{q["title"]}</h2><p>Five questions, four marks each: 20 marks total. Minimum 14/20 (70%), as required by the outline for this knowledge check. This does not authorize gauge operation.</p>'
 for i,x in enumerate(q['questions'],1):
  body+=f'<div class="practice"><h3>Question {i} · {E(x["question"])}</h3>'
  if answers:body+=MD(x['answer'])+'<p><strong>Award one mark for each:</strong> '+E('; '.join(x['marks']))+'.</p>'
  else:body+='<div class="response-space"></div>'
  body+='</div>'
 return body+'</section>'
def unit(d,answers=False):
 code=d['code'];body=f'<article class="chapter" id="chapter-{code}"><p class="eyebrow">{E("Teaching and answer guidance" if answers else "Study chapter")} · Outline {code}</p><h1>{E(clean(d["title"]))}</h1>'
 if answers:
  body+='<h2>Worked example · '+E(d['worked']['title'])+'</h2>'+MD(d['worked']['case'])+MD(d['worked']['solution'])
  for a in d['activities']:body+=f'<section class="practice" id="answer-{a["id"]}" data-activity-id="{a["id"]}"><h3>{E(a["title"])}</h3>'+MD(a['prompt'])+'<p><strong>Answer guidance.</strong></p>'+MD(a['answer'])+'<p><strong>Observe:</strong> '+E(', '.join(a['skills']))+' through the learner’s actual contribution, calculation, explanation or saved work.</p></section>'
  return body+quiz(d,True)+practical(d,True)+'</article>'
 body+=MD(d['intro']);body+='<nav class="task-route" aria-label="Learning route">'+''.join(f'<div class="route-card"><a href="#task-{code}-{s["number"]}">{E(clean(s["title"]))}</a></div>' for s in d['sections'])+'</nav>'
 # Distribute diagrams through the reading; source crops remain adjacent to the related chapter.
 visuals=list(d['visuals']);nsec=len(d['sections']);placements={}
 for i,v in enumerate(visuals):placements.setdefault(min(nsec-1,round(i*max(nsec-1,0)/max(len(visuals)-1,1))),[]).append(v)
 for i,s in enumerate(d['sections']):
  body+=f'<section id="task-{code}-{s["number"]}" data-outline-task="{code}.{s["number"]}"><p class="task-label">Learning step {s["number"]}</p><h2>{E(clean(s["title"]))}</h2>'+MD(s['text'])+'</section>'
  for v in placements.get(i,[]):body+=fig(v,f'{code}-figure-{v}')
 w=d['worked'];body+='<aside class="worked"><h2>Worked example · '+E(w['title'])+'</h2>'+MD(w['case'])+'<p><strong>Think it through.</strong></p>'+MD(w['solution'])+'</aside><h2>Try it and explain your thinking</h2>'
 for a in d['activities']:body+=f'<section class="practice" id="practice-{a["id"]}" data-activity-id="{a["id"]}"><h3>{E(a["title"])}</h3>'+MD(a['prompt'])+'<p class="small"><strong>Skills you use:</strong> '+E(', '.join(a['skills']))+'.</p><div class="response-space"></div></section>'
 return body+quiz(d)+practical(d)+references(d)+'</article>'
SKILLS=[('Reading','Identify the controlling facts, missing information and one unsupported statement in the brief.','Use the exact case facts; distinguish observation, assumption and missing authority.'),('Writing','Draft a concise handover with location, quantities, status and the next responsible action.','The note preserves verified facts, units and unresolved holds without inventing a release.'),('Numeracy','Show the case calculation with units and an independent reasonableness check.','Use the worked numerical key below; show the relationship and its practical limits.'),('Digital','Use an available AI assistant to draft a findings table and editable record from this brief. Request DOCX or a structured document, XLSX with formulas where useful, and a PDF/HTML reading copy. Audit every claim and reopen the actual outputs.','Record the product/capabilities, prompt, source facts, saved files and checks. A chat response alone is not a created or verified file. Check formulas and preserve originals.'),('Problem solving','Explain the discrepancy, what evidence is needed and who should authorize the next step.','Separate the observed issue from a guessed cause; preserve evidence and identify the correct decision role.'),('Communication','Brief a partner, ask for a check-back and repair one misunderstanding if it occurs.','Observe an actual exchange and confirmation of the essential facts; do not infer communication from a shared file.'),('Collaboration','Agree reviewer/author roles, complete a review and record each person’s contribution.','Both learners take an identifiable turn; feedback is respectful and tied to the case evidence.'),('Adaptability','Apply the change card, identify what changes and what stays, and revise the record.','Use the change-response key below; retain the earlier version and do not alter unrelated facts.'),('Creativity and innovation','Create a labelled SVG, annotated plan, short audio explanation or captioned storyboard that makes the issue easier to understand. Test it with a reader/listener and improve one useful detail.','The visual/media has accurate labels, source credits and a stated purpose. Inspect generated diagrams/media; do not invent technical settings. Keep a transcript/captions when producing audio/video.')]
def capstone(v,answers=False):
 body=f'<article class="chapter" id="integrated-case"><p class="eyebrow">Integrated practice · all nine Skills for Success</p><h1>{E(v["case_title"])}</h1><p class="study-note">This is a complete fictional classroom case. It does not describe an actual community, Nation, employer or project. Learners may use the supplied case without disclosing personal or cultural knowledge.</p>'+MD(v['brief'])
 for skill,prompt,key in SKILLS:
  body+='<section class="practice"><h2>'+skill+' · '+{'Reading':'Check the facts','Writing':'Make the handover useful','Numeracy':'Calculate and check','Digital':'Direct AI and verify the files','Problem solving':'Investigate the discrepancy','Communication':'Send and check the message','Collaboration':'Review together','Adaptability':'Respond to the change','Creativity and innovation':'Make understanding easier'}[skill]+'</h2><p>'+E(prompt)+'</p>'
  if answers:body+='<p><strong>Evidence and feedback:</strong> '+E(key)+'</p>'
  else:body+='<div class="response-space"></div>'
  body+='</section>'
 body+='<aside class="worked"><h2>Change card · Use after the first attempt</h2>'+MD(v['change'])+'</aside>'
 if answers:body+='<h2>Verified case key</h2>'+MD(v['answer'])+'<h2>Change-response key</h2>'+MD(v['change_answer'])
 body+='<h2>Individual evidence record</h2><p>Keep the brief, calculation, saved work, review findings and revision. Record each person’s actual contribution and support. Use Not observed, Not yet demonstrated, Demonstrated with support, or Demonstrated independently for the stated action; these are local feedback descriptions.</p><p>For AI/media work, a transcript, script or storyboard is distinct from a generated audio/video file. Name what was actually produced and inspected. Do not upload private records or community-held material without the relevant authority.</p></article>'
 return body
GLOSSARY={'Aggregate':'Mineral particles forming the solid skeleton of the mixture or granular layer.','Binder':'The asphalt material that coats and binds the aggregate in the specified mixture.','Compacted thickness':'Layer thickness after the required compaction process; distinct from loose depth behind the screed.','Density reference':'The specified comparison value used as the denominator of a percent-density calculation.','Gradation':'Distribution of aggregate particle sizes, commonly expressed as cumulative percent passing specified sieves.','Head of material':'The quantity/distribution of mix immediately in front of the screed.','Job mix formula (JMF)':'The accepted mixture proportions and properties under the applicable quality/contract process.','Lockout':'Isolation, securing and verification of hazardous energy for work requiring protection.','Lot / sub-lot':'Defined portions of work used for sampling, testing and acceptance under the contract.','OMM':'Operation and maintenance manual matched to the actual machine, serial range and configuration.','RAP':'Reclaimed asphalt pavement: recovered material containing aggregate and aged binder.','SDS':'Safety data sheet for the actual product; read with its label and workplace procedure.','Screed':'The paver assembly that forms the mat; its response depends on setup, material and movement.','Station / offset':'Location along an alignment / distance and direction from a defined reference.','TCP':'Traffic control person with the required training and assigned role.','Traceability':'A record connecting material, location, time, sample, result and authorized decision.','SVG':'Scalable vector graphics: useful for clear diagrams whose labels and geometry must be checked.','DOCX / XLSX':'Editable document / spreadsheet workbook; verify actual content and formulas after creation.','PDF / HTML':'Page-based reading copy / browser document; inspect completeness, access and linked resources.','MP3 / MP4 / VTT':'Audio file / video container / timed web captions; test playback and retain a transcript.'}
def intro(v,answers=False):
 return '<article class="chapter" id="start"><h1>Use this volume</h1><p>This volume provides complete classroom readings, worked examples, named practice tasks and answer guidance for '+E(v['title'].lower())+'. Follow the learning route in each chapter, study the labelled figures and explain your reasoning. The separate answer book contains the worked keys and observation records.</p><p>Care for people, place and the next person using the work runs through the cases. Local First Nations, Métis and Inuit learners and partners bring distinct knowledge and priorities. Participation does not require sharing personal stories or cultural teachings, and no diagram claims to represent a Nation’s protocol.</p><p class="study-note">Classroom authoring is complete for the listed competencies. Qualified technical review, actual fleet/site matching, a local teaching pilot and observed practical qualification are separate requirements. The practical records are ready for an instructor to configure and use; they do not certify unobserved work.</p><h2>Read the picture, then test the idea</h2><ol><li>Identify the object, process or quantity shown.</li><li>Read labels, units and the figure’s stated limits.</li><li>Connect the image to the chapter explanation.</li><li>Try the exercise and check against evidence.</li><li>Explain the result to another person and revise if needed.</li></ol><h2>Use AI as a checked working tool</h2><p>Claude and ChatGPT can help explain provided documents and create supported files. Claude Code, Cowork and Codex can help with permitted multi-file tasks and repeatable workflows when their tools are available. Give a clear purpose, named sources, output formats, limits and checks. Ask for a findings table with page/cell evidence; verify it against the source. Reopen DOCX, XLSX, HTML or PDF outputs. For study audio/video, verify the script, captions, diagrams and actual playback. A generated result is not a technical approval.</p><h2>Keep the term with its meaning</h2><dl class="glossary">'+''.join('<div><dt>'+E(k)+'</dt><dd>'+E(val)+'</dd></div>' for k,val in GLOSSARY.items())+'</dl></article>'
def shell(title,body,deck,cover=None):
 art=f'<figure class="cover-art"><img src="{E(figs[cover]["file"],quote=True)}" alt="{E(figs[cover]["alt"],quote=True)}"><figcaption>{E(figs[cover]["credit"])}</figcaption></figure>' if cover else ''
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | ACCESS IS4S</title><link rel="stylesheet" href="assets/book.css"></head><body><a class="skip" href="#content">Skip to learning material</a><header class="mast {"book-cover" if cover else ""}"><p class="brand">ACCESS · Indigenous Skills 4 Success</p><h1>{E(title)}</h1><p class="deck">{E(deck)}</p><p class="edition">Classroom development edition · 30 October 2026</p>{art}<nav class="navline"><a href="index.html">All study volumes</a><a href="coverage.html">Learning coverage</a><a href="figure-register.html">Figure credits</a></nav></header><main class="page" id="content">{body}</main></body></html>'
rows=[];placements=[]
for v in V:
 n=v['number'];toc='<nav class="contents" aria-label="Volume contents"><h2>In this volume</h2><ol><li><a href="#start">How to use the volume and key terms</a></li>'+''.join(f'<li><a href="#chapter-{c}">{E(clean(U[c]["title"]))}</a></li>' for c in v['codes'])+'<li><a href="#integrated-case">'+E(v['case_title'])+'</a></li></ol></nav>'
 for answer in [False,True]:
  stem=f'volume-{n}'+('-answers' if answer else '');title=('Teaching and answer guidance · ' if answer else '')+v['title'];body=toc+intro(v,answer)+''.join(unit(U[c],answer) for c in v['codes'])+capstone(v,answer)
  (R/(stem+'.html')).write_text(shell(title,body,f'Volume {n} · '+', '.join(v['codes']),None if answer else U[v['codes'][0]]['visuals'][0]))
 for code in v['codes']:
  d=U[code];(R/(code+'.html')).write_text(shell(clean(d['title']),unit(d),f'Volume {n} · Outline {code}'))
  md='# '+clean(d['title'])+'\n\n'+d['intro']+'\n\n'
  for s in d['sections']:md+='## '+clean(s['title'])+'\n\n'+s['text']+'\n\n'
  md+='## Worked example: '+d['worked']['title']+'\n\n'+d['worked']['case']+'\n\n'+d['worked']['solution']+'\n\n'
  for a in d['activities']:md+='## '+a['title']+'\n\n'+a['prompt']+'\n\n'
  (R/(code+'.md')).write_text(md.rstrip()+'\n')
  for s in d['sections']:rows.append({'competency':code,'title':d['title'],'outline_task':s['number'],'task_wording':s['title'],'volume':n,'chapter':code+'.html#task-'+code+'-'+str(s['number']),'authored_reading':True,'practice_count':len(d['activities']),'answer_book':f'volume-{n}-answers.html#chapter-{code}','technical_review':'Pending','practical_qualification':'Not claimed'})
  for f in d['visuals']:placements.append({'chapter':code,'figure':f,'file':figs[f]['file'],'sha256':figs[f]['sha256']})
with (R/'coverage.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
(R/'coverage.json').write_text(json.dumps(rows,indent=2)+'\n');(R/'image-inventory.json').write_text(json.dumps({'placements':len(placements),'unique_figures':len(used),'images':placements},indent=2)+'\n')
body='<article class="chapter"><h1>Complete learning-task coverage</h1><p>61 competency chapters cover all 218 learning tasks from B2 through L6. Each task has an authored reading section; each chapter has worked examples, three named activities, answer guidance, source/figure credits and a supervised observation record. Seven integrated cases provide individual evidence across all nine Skills for Success. <a href="coverage.csv">Download the full task map</a>.</p><p>Authored classroom materials are complete. Technical review, actual machine/site configuration, pilot and observed practical qualification remain separately recorded.</p>'
for v in V:body+='<h2>Volume '+str(v['number'])+' · '+E(v['title'])+'</h2><ul>'+''.join(f'<li><a href="{c}.html">{E(clean(U[c]["title"]))}</a> · {c} · {len(U[c]["sections"])} learning tasks · <a href="volume-{v["number"]}-answers.html#chapter-{c}">answer guidance</a></li>' for c in v['codes'])+'</ul>'
(R/'coverage.html').write_text(shell('Learning-task coverage',body+'</article>','B2–L6 · all 218 tasks'))
body='<article class="chapter"><h1>Study the work, understand the equipment</h1><p>Seven complete volumes continue the asphalt study sequence through compaction and final shutdown. Choose a topic by its name. Each volume includes readings, labelled visuals, worked examples, practice and a separate teaching/answer book.</p><p><a href="../index.html">Foundations and safe work · Volume 1</a> · <a href="coverage.html">All learning tasks</a> · <a href="sources/rosco-rb50-manual.pdf">Rosco RB50 manual</a> · <a href="sources/rosco-rb50-small-parts.zip">Small manual parts ZIP</a></p><div class="volume-grid">'
for v in V:
 n=v['number'];body+=f'<section class="volume-card"><p class="eyebrow">Volume {n}</p><h2>{E(v["title"])}</h2><p>{len(v["codes"])} chapters · '+E(v['codes'][0]+'–'+v['codes'][-1])+f'</p><p><a href="volume-{n}.html">Read the study book</a> · <a href="volume-{n}.pdf">Study PDF</a> · <a href="volume-{n}-print-pack.zip">Download both PDFs</a></p><p><a href="volume-{n}-answers.html">Teaching and answers</a> · <a href="volume-{n}-answers.pdf">Answer PDF</a></p></section>'
